  for (let iv = 0; iv < 2; iv++) {
    for (let iu = 0; iu < 2; iu++) {
      positions.push(ox + ux * iu + vx * iv, oy + uy * iu + vy * iv, oz + uz * iu + vz * iv);
      normals.push(nx, ny, nz);
      uvs.push(iu, iv);
    }
  }
  indices.push(start, start + 1, start + 3, start, start + 3, start + 2);
};

